const fs=require('fs');
const {execFileSync}=require('child_process');
const ua='Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120 Safari/537.36';
const reqs=[
 ['Press Start 2P','https://fonts.googleapis.com/css2?family=Press+Start+2P&display=swap','pressstart2p'],
 ['VT323','https://fonts.googleapis.com/css2?family=VT323&display=swap','vt323'],
 ['Cormorant Garamond Light Italic','https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@1,300&display=swap','cormorant-italic'],
 ['Cormorant Garamond Regular','https://fonts.googleapis.com/css2?family=Cormorant+Garamond:wght@400&display=swap','cormorant-regular'],
 ['Cormorant Garamond SemiBold','https://fonts.googleapis.com/css2?family=Cormorant+Garamond:wght@600&display=swap','cormorant-semibold'],
];
for(const [name,url,file] of reqs){
 const css=execFileSync('curl',['-s','-A',ua,url],{encoding:'utf8'});
 const blocks=css.split('/* latin */');
 let m=blocks[1]?.match(/src: url\((https:[^)]+)\)/);
 if(!m){console.log('no latin block',name);continue;}
 execFileSync('curl',['-s','-o',file+'.woff2',m[1]]);
 console.log(file, fs.statSync(file+'.woff2').size);
}
EOF
