:root {
  --ink: #070610;
  --violet: #a879ff;
  --violet-soft: #c9a9ff;
  --ivory: #f6f1ff;
  --gold: #ffd888;
  --muted: #a79dbd;
}

* { box-sizing: border-box; }

html, body {
  height: 100%;
  margin: 0;
  background: #050409;
  overflow: hidden;
  color: var(--ivory);
  font-family: 'Cormorant', Georgia, serif;
  -webkit-font-smoothing: antialiased;
}

body {
  display: flex;
  align-items: center;
  justify-content: center;
}

#stage {
  position: relative;
  width: min(100vw, calc(100vh * 16 / 9));
  height: min(100vh, calc(100vw * 9 / 16));
  overflow: hidden;
  background: #070616;
  container-type: size;
  box-shadow: 0 0 120px rgba(94, 63, 185, .22);
  isolation: isolate;
}

#game {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  image-rendering: auto;
}

/* ---------------- Screens ---------------- */

.screen {
  position: absolute;
  inset: 0;
  z-index: 5;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: opacity .7s ease, visibility .7s;
}

.screen.hidden {
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
}

#title-screen {
  background:
    radial-gradient(ellipse at 50% 56%, rgba(21, 12, 48, 0) 20%, rgba(5, 4, 13, .38) 69%, rgba(3, 3, 9, .82) 100%),
    linear-gradient(to bottom, rgba(3, 4, 14, .22), rgba(3, 3, 10, .05) 45%, rgba(3, 3, 9, .58));
