133: function sound(kind) {
134:   if (!audioEnabled) return;
135:   initAudio();
136:   if (!audioContext) return;
137:   const now = audioContext.currentTime;
138:   const tones = {
139:     start: [[392, .15, 'sine', .06], [523.25, .3, 'sine', .045]],
140:     select: [[660, .07, 'sine', .025]],
141:     hit: [[140, .15, 'triangle', .05], [95, .18, 'sine', .025]],
142:     hurt: [[180, .2, 'sawtooth', .035]],
143:     heal: [[523, .12, 'sine', .04], [783.99, .28, 'sine', .035]],
144:     act: [[440, .12, 'sine', .035], [587.33, .22, 'sine', .035]],
145:     dodge: [[740, .05, 'sine', .025]],
146:     spare: [[659.25, .2, 'sine', .04], [880, .35, 'sine', .035]],
147:   }[kind] || [];
148:   for (const [freq, dur, type, vol] of tones) {
149:     const osc = audioContext.createOscillator(), gain = audioContext.createGain();
150:     osc.type = type; osc.frequency.setValueAtTime(freq, now);
151:     gain.gain.setValueAtTime(vol, now); gain.gain.exponentialRampToValueAtTime(.0001, now + dur);
152:     osc.connect(gain); gain.connect(audioContext.destination); osc.start(now); osc.stop(now + dur);
153:   }
154: }
