164: function update(dt) {
165:   if (!state) return;
166:   state.timer += dt;
167:   state.messageTimer = Math.max(0, state.messageTimer - dt);
168:   state.menuLock = Math.max(0, state.menuLock - dt);
169:   state.screenShake = Math.max(0, state.screenShake - dt * 30);
170:   state.flash = Math.max(0, state.flash - dt * 1.5);
171:   state.exprTimer = Math.max(0, state.exprTimer - dt);
172:   state.soul.invuln = Math.max(0, state.soul.invuln - dt);
173:   state.soul.blink += dt;
174:   updateParticles(dt);
175:   if (state.pause || titleScreen.classList.contains('hidden') === false || !endingScreen.classList.contains('hidden')) return;
176:   if (state.phase === 'dodge') updateDodge(dt);
177:   else if (state.phase === 'attack') updateAttack(dt);
178:   else if (state.phase === 'transition' && state.turnCue > 0) {
179:     state.turnCue -= dt;
180:     if (state.turnCue <= 0) startBossTurn();
181:   }
182:   if (state.bossHp <= 0 && state.phase !== 'ending') endGame('dark');
183:   if (state.hp <= 0 && state.phase !== 'ending') endGame('consumed');
184: }
