186: function updateParticles(dt) {
187:   for (const p of motes) {
188:     p.y -= p.speed * dt;
189:     p.x += Math.sin(elapsed * .45 + p.phase) * dt * 5;
190:     if (p.y < 240) { p.y = 690; p.x = rand(0, W); }
191:   }
192:   for (let i = state.particles.length - 1; i >= 0; i--) {
193:     const p = state.particles[i];
194:     p.x += (p.vx || 0) * dt; p.y += (p.vy || 0) * dt;
195:     p.vy = (p.vy || 0) + (p.gravity || 0) * dt;
196:     p.life -= dt;
197:     if (p.life <= 0) state.particles.splice(i, 1);
198:   }
199: }
