201: function updateDodge(dt) {
202:   const soul = state.soul, box = state.arena;
203:   const speed = 250;
204:   let dx = 0, dy = 0;
205:   if (keys.has('ArrowLeft') || keys.has('a')) dx--;
206:   if (keys.has('ArrowRight') || keys.has('d')) dx++;
207:   if (keys.has('ArrowUp') || keys.has('w')) dy--;
208:   if (keys.has('ArrowDown') || keys.has('s')) dy++;
209:   if (pointer.active && pointer.down) {
210:     const px = pointer.x, py = pointer.y;
211:     dx += clamp((px - soul.x) / 55, -1, 1);
212:     dy += clamp((py - soul.y) / 55, -1, 1);
213:   }
214:   const len = Math.hypot(dx, dy) || 1;
215:   soul.vx = lerp(soul.vx, dx / len * speed, 1 - Math.exp(-dt * 13));
216:   soul.vy = lerp(soul.vy, dy / len * speed, 1 - Math.exp(-dt * 13));
217:   soul.x = clamp(soul.x + soul.vx * dt, box.x + 14, box.x + box.w - 14);
218:   soul.y = clamp(soul.y + soul.vy * dt, box.y + 14, box.y + box.h - 14);
219:   const oldCount = state.bullets.length;
220:   for (let i = state.bullets.length - 1; i >= 0; i--) {
221:     const b = state.bullets[i];
222:     b.x += b.vx * dt; b.y += b.vy * dt; b.life -= dt;
223:     if (b.spin) b.angle += b.spin * dt;
224:     if (b.life <= 0 || b.x < box.x - 55 || b.x > box.x + box.w + 55 || b.y < box.y - 55 || b.y > box.y + box.h + 55) {
225:       state.bullets.splice(i, 1); continue;
226:     }
227:     const dx = soul.x - b.x, dy = soul.y - b.y;
228:     if (soul.invuln <= 0 && dx * dx + dy * dy < (b.r + 9) ** 2) hitPlayer(b);
229:   }
230:   state.timer -= dt;
231:   if (state.timer <= 0) finishDodge();
232: }
