423: function spawnPattern(dt) {
424:   const t = state.timer;
425:   const box = state.arena;
426:   const difficulty = Math.min(1 + state.turn * .07, 1.42);
427:   state.spawnClock = (state.spawnClock || 0) - dt;
428:   if (state.spawnClock > 0) return;
429:   if (state.pattern === 0) {
430:     const count = state.turn > 3 ? 3 : 2;
431:     for (let i = 0; i < count; i++) {
432:       const x = rand(box.x + 22, box.x + box.w - 22);
433:       addBullet(x, box.y - 12, Math.PI / 2 + rand(-.12, .12), rand(94, 135) * difficulty,
434:         { color: pick(['#fff1c8', '#d2bdff', '#b6e4ff']), r: 5.5, damage: 4, type: 'star' });
435:     }
436:     state.spawnClock = .46 / difficulty;
437:   } else if (state.pattern === 1) {
438:     const side = Math.floor(t * 3) % 2;
439:     const x = side === 0 ? box.x - 12 : box.x + box.w + 12;
440:     const y = box.y + 35 + (Math.sin(t * 2.2) + 1) * box.h * .32;
441:     const ang = Math.atan2(state.soul.y - y, state.soul.x - x) + rand(-.25, .25);
442:     addBullet(x, y, ang, rand(95, 135) * difficulty, { color: '#b997ef', r: 8, damage: 6, type: 'orb', spin: 3 });
443:     if (state.turn > 2 && Math.random() < .4) addBullet(x, box.y + box.h - (y - box.y), ang + .2, 95 * difficulty, { color: '#f3d9ff', r: 5, damage: 4, type: 'star' });
444:     state.spawnClock = .38 / difficulty;
445:   } else if (state.pattern === 2) {
446:     const cx = box.x + box.w / 2, cy = box.y + box.h / 2;
447:     const n = state.turn > 2 ? 3 : 2;
448:     const base = elapsed * .95 + t * .3;
449:     for (let i = 0; i < n; i++) {
450:       const a = base + i * TAU / n;
451:       addBullet(cx + Math.cos(a) * (box.w * .55), cy + Math.sin(a) * (box.h * .58), a + Math.PI + .35,
452:         88 * difficulty, { color: i % 2 ? '#f5e1ff' : '#ad9cef', r: 6.5, damage: 5, type: 'orb', spin: 2 });
453:     }
454:     state.spawnClock = .52 / difficulty;
455:   } else {
456:     const lanes = [box.x + 44, box.x + box.w - 44];
457:     const lane = lanes[Math.floor(Math.random() * lanes.length)];
458:     const width = state.turn > 3 ? 4 : 3;
459:     for (let i = 0; i < width; i++) {
460:       const x = lane + rand(-18, 18);
461:       addBullet(x, box.y - 12 - i * 22, Math.PI / 2 + (x < box.x + box.w / 2 ? .14 : -.14),
462:         115 * difficulty, { color: i === 1 ? '#fff4d8' : '#b9a2ff', r: 5 + (i % 2), damage: 4, type: 'shard' });
463:     }
464:     if (state.turn > 4) {
465:       const sx = Math.random() < .5 ? box.x - 10 : box.x + box.w + 10;
466:       addBullet(sx, rand(box.y + 30, box.y + box.h - 20), sx < box.x ? 0 : Math.PI, 100 * difficulty,
467:         { color: '#f3d9ff', r: 6, damage: 5, type: 'orb' });
468:     }
469:     state.spawnClock = .68 / difficulty;
470:   }
471: }
472: function updateDodge(dt) {
