447: function updateDodge(dt) {
448:   const soul = state.soul, box = state.arena;
449:   const speed = 250;
450:   let dx = 0, dy = 0;
451:   if (keys.has('ArrowLeft') || keys.has('a')) dx--;
452:   if (keys.has('ArrowRight') || keys.has('d')) dx++;
453:   if (keys.has('ArrowUp') || keys.has('w')) dy--;
454:   if (keys.has('ArrowDown') || keys.has('s')) dy++;
455:   if (pointer.active && pointer.down) {
456:     dx += clamp((pointer.x - soul.x) / 55, -1, 1);
457:     dy += clamp((pointer.y - soul.y) / 55, -1, 1);
458:   }
459:   const len = Math.hypot(dx, dy) || 1;
460:   soul.vx = lerp(soul.vx, dx / len * speed, 1 - Math.exp(-dt * 13));
461:   soul.vy = lerp(soul.vy, dy / len * speed, 1 - Math.exp(-dt * 13));
462:   soul.x = clamp(soul.x + soul.vx * dt, box.x + 14, box.x + box.w - 14);
463:   soul.y = clamp(soul.y + soul.vy * dt, box.y + 14, box.y + box.h - 14);
464:   if (state.turnCue > 0) state.turnCue = Math.max(0, state.turnCue - dt);
465:   else spawnPattern(dt);
466:   for (let i = state.bullets.length - 1; i >= 0; i--) {
467:     const b = state.bullets[i];
468:     b.x += b.vx * dt; b.y += b.vy * dt; b.life -= dt;
469:     if (b.spin) b.angle += b.spin * dt;
470:     if (b.life <= 0 || b.x < box.x - 55 || b.x > box.x + box.w + 55 || b.y < box.y - 55 || b.y > box.y + box.h + 55) {
471:       state.bullets.splice(i, 1); continue;
472:     }
473:     const bx = soul.x - b.x, by = soul.y - b.y;
474:     if (soul.invuln <= 0 && bx * bx + by * by < (b.r + 9) ** 2) hitPlayer(b);
475:   }
476:   state.timer -= dt;
477:   if (state.timer <= 0) finishDodge();
478: }
